/**
 * Seeds campus buildings (A–I), classrooms, academic faculties,
 * course offerings, class schedules, demo students, and enrollments.
 * All primary keys are generated by PostgreSQL and chained via `.returning()`.
 * Run with: bun run db:seed
 */
import { config } from "dotenv";
import { sql } from "drizzle-orm";
import { drizzle } from "drizzle-orm/node-postgres";
import { createInsertSchema } from "drizzle-orm/zod";
import type { z } from "zod";
import { DEFAULT_ROOM } from "../lib/room.ts";
import { relations } from "./relations.ts";
import {
	buildings,
	classSchedules,
	courses,
	faculties,
	rooms,
	studentSchedules,
	students,
} from "./schema.ts";

config({ path: [".env.local", ".env"] });

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) throw new Error("DATABASE_URL is not set");

const FACULTY_CODES = ["FCS", "FEB", "FIB", "FTE", "FBM", "FTI"] as const;
type FacultyCode = (typeof FACULTY_CODES)[number];

function isFacultyCode(value: string): value is FacultyCode {
	return (FACULTY_CODES as readonly string[]).includes(value);
}

const insertBuildingSchema = createInsertSchema(buildings);
const insertFacultySchema = createInsertSchema(faculties);
const insertRoomSchema = createInsertSchema(rooms);
const insertCourseSchema = createInsertSchema(courses);
const insertClassScheduleSchema = createInsertSchema(classSchedules);
const insertStudentSchema = createInsertSchema(students);
const insertStudentScheduleSchema = createInsertSchema(studentSchedules);

const scheduleSlotSchema = insertClassScheduleSchema.omit({
	id: true,
	courseId: true,
	roomId: true,
	createdAt: true,
});
const studentSeedInputSchema = insertStudentSchema.pick({
	name: true,
	photoUrl: true,
});

const db = drizzle(databaseUrl, { relations });

