const ACADEMIC_TERM = "2026/2027-Odd";

/**
 * Creates 10 conflict-free weekly class schedule slots for a faculty's 10 courses:
 * - Slots 0..4 (courses 101–105): core weekday cohort sessions (Mon–Fri)
 * - Slots 5..9 (courses 106–110): complementary weekday sessions with zero time overlap
 */
function buildFacultyScheduleSlots(
	instructors: readonly [string, string, string, string, string],
): z.infer<typeof scheduleSlotSchema>[] {
	const [inst1, inst2, inst3, inst4, inst5] = instructors;
	return [
		// Core cohort courses (101–105)
		{
			section: "A",
			instructor: inst1,
			dayOfWeek: "Monday",
			startTime: "09:00",
			endTime: "11:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst2,
			dayOfWeek: "Tuesday",
			startTime: "13:00",
			endTime: "15:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst3,
			dayOfWeek: "Wednesday",
			startTime: "09:00",
			endTime: "11:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst4,
			dayOfWeek: "Thursday",
			startTime: "10:00",
			endTime: "12:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst5,
			dayOfWeek: "Friday",
			startTime: "13:30",
			endTime: "16:00",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		// Upper / elective courses (106–110) — non-overlapping time slots
		{
			section: "A",
			instructor: inst2,
			dayOfWeek: "Monday",
			startTime: "13:00",
			endTime: "15:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst3,
			dayOfWeek: "Tuesday",
			startTime: "09:00",
			endTime: "11:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst4,
			dayOfWeek: "Wednesday",
			startTime: "13:00",
			endTime: "15:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst5,
			dayOfWeek: "Thursday",
			startTime: "13:30",
			endTime: "16:00",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
		{
			section: "A",
			instructor: inst1,
			dayOfWeek: "Friday",
			startTime: "09:00",
			endTime: "11:30",
			academicTerm: ACADEMIC_TERM,
			maxCapacity: 30,
		},
	];
}

