// 1. Seed Buildings (UUIDs generated by PostgreSQL)
const insertedBuildings = await db
	.insert(buildings)
	.values(campusBuildings)
	.onConflictDoUpdate({
		target: buildings.code,
		set: {
			name: sql`excluded.name`,
			purpose: sql`excluded.purpose`,
			hasClasses: sql`excluded.has_classes`,
			totalFloors: sql`excluded.total_floors`,
		},
	})
	.returning({
		id: buildings.id,
		code: buildings.code,
		totalFloors: buildings.totalFloors,
		hasClasses: buildings.hasClasses,
		purpose: buildings.purpose,
		name: buildings.name,
	});

// 2. Generate roomDefinitions & link facultyDefinitions using returned building UUIDs
for (const building of insertedBuildings) {
	if (building.hasClasses) {
		for (let floor = 1; floor <= building.totalFloors; floor++) {
			for (let roomNum = 1; roomNum <= 5; roomNum++) {
				const roomCode = `${building.code.toLowerCase()}.${floor}.${roomNum}`;
				roomDefinitions.push({
					code: roomCode,
					buildingId: building.id,
					floor,
					roomNumber: roomNum.toString(),
					name: `Room ${roomCode.toUpperCase()}`,
					capacity: 30 + floor * 10,
				});
			}
		}
	}

	const normalizedPurpose = building.purpose.toLocaleLowerCase();
	for (const faculty of facultyDefinitions) {
		const disciplineName = faculty.name
			.replace(/^Fakultas\s+/i, "")
			.toLocaleLowerCase();
		if (normalizedPurpose.includes(disciplineName)) {
			faculty.buildingId = building.id;
		}
	}
}

for (const faculty of facultyDefinitions) {
	if (!faculty.buildingId) {
		throw new Error(`Home building for faculty ${faculty.code} not found`);
	}
}

// 3. Seed Rooms & Faculties
const insertedRooms = await db
	.insert(rooms)
	.values(roomDefinitions)
	.onConflictDoUpdate({
		target: rooms.code,
		set: {
			buildingId: sql`excluded.building_id`,
			floor: sql`excluded.floor`,
			roomNumber: sql`excluded.room_number`,
			name: sql`excluded.name`,
			capacity: sql`excluded.capacity`,
		},
	})
	.returning({
		id: rooms.id,
		code: rooms.code,
		buildingId: rooms.buildingId,
		floor: rooms.floor,
		roomNumber: rooms.roomNumber,
	});

const roomsByBuildingId = new Map<string, typeof insertedRooms>();
for (const room of [...insertedRooms].sort(
	(a, b) => a.floor - b.floor || Number(a.roomNumber) - Number(b.roomNumber),
)) {
	const list = roomsByBuildingId.get(room.buildingId) ?? [];
	list.push(room);
	roomsByBuildingId.set(room.buildingId, list);
}

const insertedFaculties = await db
	.insert(faculties)
	.values(facultyDefinitions)
	.onConflictDoUpdate({
		target: faculties.code,
		set: {
			name: sql`excluded.name`,
			buildingId: sql`excluded.building_id`,
		},
	})
	.returning({
		id: faculties.id,
		code: faculties.code,
		name: faculties.name,
		buildingId: faculties.buildingId,
	});

const facultyByCode = new Map<
	FacultyCode,
	(typeof insertedFaculties)[number]
>();
const facultyCodeById = new Map<string, FacultyCode>();
for (const faculty of insertedFaculties) {
	if (isFacultyCode(faculty.code)) {
		facultyByCode.set(faculty.code, faculty);
		facultyCodeById.set(faculty.id, faculty.code);
	}
}

// 4. Link courses to returned faculty UUIDs & seed Courses
for (const course of courseDefinition) {
	const prefix = course.code.split("-")[0] ?? "";
	const faculty = isFacultyCode(prefix) ? facultyByCode.get(prefix) : undefined;
	if (!faculty) {
		throw new Error(`Faculty for course ${course.code} not found`);
	}
	course.facultyId = faculty.id;
}

const insertedCourses = await db
	.insert(courses)
	.values(courseDefinition)
	.onConflictDoUpdate({
		target: courses.code,
		set: {
			name: sql`excluded.name`,
			credits: sql`excluded.credits`,
			description: sql`excluded.description`,
			facultyId: sql`excluded.faculty_id`,
		},
	})
	.returning({
		id: courses.id,
		code: courses.code,
		facultyId: courses.facultyId,
	});

const coursesByFaculty = new Map<
	FacultyCode,
	(typeof insertedCourses)[number][]
>();
for (const course of [...insertedCourses].sort((a, b) =>
	a.code.localeCompare(b.code),
)) {
	const facultyCode = course.facultyId
		? facultyCodeById.get(course.facultyId)
		: undefined;
	if (!facultyCode) continue;
	const list = coursesByFaculty.get(facultyCode) ?? [];
	list.push(course);
	coursesByFaculty.set(facultyCode, list);
}

// 5. Pair returned courses + rooms with scheduleDefinitions & seed Class Schedules
const facultiesByBuildingId = new Map<string, FacultyCode[]>();
for (const code of FACULTY_CODES) {
	const faculty = facultyByCode.get(code);
	if (!faculty?.buildingId) continue;
	const list = facultiesByBuildingId.get(faculty.buildingId) ?? [];
	list.push(code);
	facultiesByBuildingId.set(faculty.buildingId, list);
}

const schedulesToInsert: z.infer<typeof insertClassScheduleSchema>[] = [];

for (const code of FACULTY_CODES) {
	const faculty = facultyByCode.get(code);
	if (!faculty?.buildingId) {
		throw new Error(`Faculty ${code} missing buildingId`);
	}

	const buildingRooms = roomsByBuildingId.get(faculty.buildingId) ?? [];
	const buildingFaculties = facultiesByBuildingId.get(faculty.buildingId) ?? [
		code,
	];
	const shareIndex = buildingFaculties.indexOf(code);
	const sliceSize = Math.floor(buildingRooms.length / buildingFaculties.length);
	const facultyRooms = buildingRooms.slice(
		shareIndex * sliceSize,
		(shareIndex + 1) * sliceSize,
	);

	// Pin FCS core weekday classes to DEFAULT_ROOM (h.2.4) so the home screen demo works every day
	const preferredRoom =
		code === "FCS"
			? facultyRooms.find((r) => r.code === DEFAULT_ROOM.toLowerCase())
			: undefined;
	const primaryRoom = preferredRoom ?? facultyRooms[0];
	if (!primaryRoom) {
		throw new Error(`No primary room available for faculty ${code}`);
	}
	const secondaryRooms = facultyRooms.filter((r) => r.id !== primaryRoom.id);

	const facultyCourses = coursesByFaculty.get(code) ?? [];
	const slotTemplates = scheduleDefinitions[code];

	facultyCourses.forEach((course, idx) => {
		const slot = slotTemplates[idx];
		if (!slot) {
			throw new Error(`Missing schedule slot ${idx} for faculty ${code}`);
		}
		const targetRoom =
			idx < 5
				? primaryRoom
				: (secondaryRooms[(idx - 5) % secondaryRooms.length] ?? primaryRoom);

		schedulesToInsert.push({
			...slot,
			courseId: course.id,
			roomId: targetRoom.id,
		});
	});
}

const insertedSchedules = await db
	.insert(classSchedules)
	.values(schedulesToInsert)
	.onConflictDoUpdate({
		target: [
			classSchedules.courseId,
			classSchedules.section,
			classSchedules.academicTerm,
		],
		set: {
			roomId: sql`excluded.room_id`,
			instructor: sql`excluded.instructor`,
			dayOfWeek: sql`excluded.day_of_week`,
			startTime: sql`excluded.start_time`,
			endTime: sql`excluded.end_time`,
			maxCapacity: sql`excluded.max_capacity`,
		},
	})
	.returning({
		id: classSchedules.id,
		courseId: classSchedules.courseId,
		roomId: classSchedules.roomId,
		section: classSchedules.section,
		academicTerm: classSchedules.academicTerm,
	});

const scheduleIdByCourseId = new Map<string, string>();
for (const schedule of insertedSchedules) {
	if (schedule.courseId) {
		scheduleIdByCourseId.set(schedule.courseId, schedule.id);
	}
}

// 6. Generate 60 demoStudents (10 per faculty) using returned faculty names & seed Students
const demoStudents: z.infer<typeof insertStudentSchema>[] = [];
for (const code of FACULTY_CODES) {
	const faculty = facultyByCode.get(code);
	if (!faculty) {
		throw new Error(`Faculty ${code} not found when building students`);
	}
	demoStudentsByFaculty[code].forEach((student, idx) => {
		demoStudents.push({
			studentId: `STU-${code}-${String(idx + 1).padStart(3, "0")}`,
			name: student.name,
			department: faculty.name,
			photoUrl: student.photoUrl ?? null,
		});
	});
}

const insertedStudents = await db
	.insert(students)
	.values(demoStudents)
	.onConflictDoUpdate({
		target: students.studentId,
		set: {
			name: sql`excluded.name`,
			department: sql`excluded.department`,
			photoUrl: sql`excluded.photo_url`,
		},
	})
	.returning({
		id: students.id,
		studentId: students.studentId,
		department: students.department,
	});

const studentsByFaculty = new Map<
	FacultyCode,
	(typeof insertedStudents)[number][]
>();
for (const student of [...insertedStudents].sort((a, b) =>
	a.studentId.localeCompare(b.studentId),
)) {
	const codePart = student.studentId.split("-")[1] ?? "";
	if (!isFacultyCode(codePart)) continue;
	const list = studentsByFaculty.get(codePart) ?? [];
	list.push(student);
	studentsByFaculty.set(codePart, list);
}

// 7. Cohort Auto-Enrollment using returned student & schedule UUIDs
// Each student takes all 5 core weekday courses (101–105) + 2 non-clashing upper courses (106–110) = 7 courses (21 SKS)
const studentSchedulesToInsert: z.infer<typeof insertStudentScheduleSchema>[] =
	[];

for (const code of FACULTY_CODES) {
	const facultyStudents = studentsByFaculty.get(code) ?? [];
	const facultyCourses = coursesByFaculty.get(code) ?? [];
	const facultyScheduleIds = facultyCourses.map((course) => {
		const scheduleId = scheduleIdByCourseId.get(course.id);
		if (!scheduleId) {
			throw new Error(`Schedule for course ${course.code} not found`);
		}
		return scheduleId;
	});

	const coreScheduleIds = facultyScheduleIds.slice(0, 5);
	const upperScheduleIds = facultyScheduleIds.slice(5, 10);

	facultyStudents.forEach((student, studentIdx) => {
		const targetScheduleIds = [...coreScheduleIds];
		if (upperScheduleIds.length > 0) {
			const firstUpper = upperScheduleIds[studentIdx % upperScheduleIds.length];
			const secondUpper =
				upperScheduleIds[(studentIdx + 1) % upperScheduleIds.length];
			if (firstUpper) targetScheduleIds.push(firstUpper);
			if (secondUpper && secondUpper !== firstUpper) {
				targetScheduleIds.push(secondUpper);
			}
		}

		for (const classScheduleId of targetScheduleIds) {
			studentSchedulesToInsert.push({
				studentId: student.id,
				classScheduleId,
				status: "enrolled",
			});
		}
	});
}

const insertedEnrollments = await db
	.insert(studentSchedules)
	.values(studentSchedulesToInsert)
	.onConflictDoUpdate({
		target: [studentSchedules.studentId, studentSchedules.classScheduleId],
		set: {
			status: sql`excluded.status`,
		},
	})
	.returning({ id: studentSchedules.id });

